/// Sentinel for "this threshold can never be reached".
pub const NEVER: u16 = 0xffff;

bitflags::bitflags! {
    /// Tag bits for MAT_TAGS. Bit order is fixed by
    /// tools/contentc/schema/block.ts.
    #[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
    pub struct Tag: u32 {
        const ROCK = 1 << 0;
        const SOIL = 1 << 1;
        const ORE = 1 << 2;
        const LIQUID = 1 << 3;
        const GAS = 1 << 4;
        const FLORA = 1 << 5;
        const FOLIAGE = 1 << 6;
        const ICE = 1 << 7;
        const HAZARD = 1 << 8;
        const DIGGABLE = 1 << 9;
        const BUILDABLE = 1 << 10;
    }
}

bitflags::bitflags! {
    /// Texture pattern values for MAT_TEXTURE. One bit each, so a value is also a
    /// mask: `TEX.grain | TEX.speckle` is a legal 'either of these' test. Bit
    /// order is fixed by tools/contentc/schema/block.ts.
    #[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
    pub struct Tex: u32 {
        const FLAT = 1 << 0;
        const SPECKLE = 1 << 1;
        const GRAIN = 1 << 2;
        const CRYSTALLINE = 1 << 3;
        const LAYERED = 1 << 4;
        const FIBROUS = 1 << 5;
        const MOLTEN = 1 << 6;
        const GLASSY = 1 << 7;
    }
}

