/// `true` when the `GROW_ONTO` pair matrix has the (a, b) bit set.
#[inline]
pub fn grow_onto(a: u16, b: u16) -> bool {
    let i = a as usize * 60 + b as usize;
    i < 3600 && (GROW_ONTO_BITS[i >> 3] >> (i & 7)) & 1 != 0
}

